const OPISY: Record<Kategoria, string> = {
  dziewczynki: "Wygodne ubranko dla dziewczynki z miękkiej, przyjaznej skórze tkaniny. Świetne na co dzień — do przedszkola, szkoły i na zabawę.",
  chlopcy: "Wygodne ubranko dla chłopca z wytrzymałego, miękkiego materiału. Gotowe na każdą przygodę — od placu zabaw po szkołę.",
  niemowleta: "Delikatne ubranko dla najmłodszych z przyjaznej skórze bawełny. Łatwe zakładanie i pełen komfort maluszka.",
};

export function opisProduktu(p: Produkt): string {
  return p.opis ?? OPISY[p.kategoria];
}

export function znajdzProdukt(id: string): Produkt | undefined {
  return PRODUKTY.find((p) => p.id === id);
}

/** Reprezentatywny produkt danej kategorii (pierwszy ze zdjęciem) — do kafli/hero. */
export function reprKategorii(kategoria: Kategoria): Produkt | undefined {
  return PRODUKTY.find((p) => p.kategoria === kategoria && p.zdjecie) ?? PRODUKTY.find((p) => p.kategoria === kategoria);
}
